PRAGMA foreign_keys = ON;

-- Canonical cross-tool classification. The existing places.category remains the
-- backward-compatible primary category; collections provide many-to-many membership.
INSERT OR IGNORE INTO categories(code,label_en,label_it,display_order) VALUES ('BOOKSHOP','Bookshops','Librerie',11);
CREATE TABLE IF NOT EXISTS place_collections (place_id TEXT NOT NULL REFERENCES places(id) ON DELETE CASCADE, collection_code TEXT NOT NULL REFERENCES categories(code), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(place_id, collection_code));
CREATE INDEX IF NOT EXISTS idx_place_collections_collection ON place_collections(collection_code, place_id);
INSERT OR IGNORE INTO place_collections(place_id,collection_code) SELECT id,category FROM places;
CREATE TABLE IF NOT EXISTS bookshop_details (place_id TEXT PRIMARY KEY REFERENCES places(id) ON DELETE CASCADE, source_bookshop_id TEXT NOT NULL UNIQUE, branch_name TEXT NOT NULL DEFAULT '', ownership TEXT NOT NULL DEFAULT '', shop_type TEXT NOT NULL, address TEXT NOT NULL, postcode TEXT NOT NULL DEFAULT '', tfl_zone TEXT NOT NULL DEFAULT '', station_name TEXT NOT NULL DEFAULT '', stock_json TEXT NOT NULL DEFAULT '[]', stock_it_json TEXT NOT NULL DEFAULT '[]', specialisms_json TEXT NOT NULL DEFAULT '[]', specialisms_it_json TEXT NOT NULL DEFAULT '[]', specialism_tags_json TEXT NOT NULL DEFAULT '[]', features_json TEXT NOT NULL DEFAULT '[]', features_it_json TEXT NOT NULL DEFAULT '[]', feature_tags_json TEXT NOT NULL DEFAULT '[]', heritage_en TEXT NOT NULL DEFAULT '', heritage_it TEXT NOT NULL DEFAULT '', source_url TEXT NOT NULL DEFAULT '', confidence TEXT NOT NULL DEFAULT 'medium', last_verified_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_bookshop_details_type ON bookshop_details(shop_type, tfl_zone);

